namespace ghidra.async;





public class AsyncPairingQueue<T> {
	private Deque<CompletableFuture<T>> givers = new();
	private Deque<CompletableFuture<T>> takers = new();

	public void give(CompletableFuture<T> giver) {
		CompletableFuture<T> taker;
		lock (givers) {
			if (takers.isEmpty()) {
				givers.add(giver);
				return;
			}
			taker = takers.poll();
		}
		pair(giver, taker);
	}

	public CompletableFuture<T> give() {
		CompletableFuture<T> giver = new();
		give(giver);
		return giver;
	}

	public CompletableFuture<T> take() {
		CompletableFuture<T> taker = new();
		CompletableFuture<T> giver;
		lock (givers) {
			if (givers.isEmpty()) {
				takers.add(taker);
				return taker;
			}
			giver = givers.poll();
		}
		pair(giver, taker);
		return taker;
	}

	private void pair(CompletableFuture<T> giver, CompletableFuture<T> taker) {
		giver.handle((val, exc) => {
			if (exc != null) {
				taker.completeExceptionally(exc);
			}
			else {
				taker.complete(val);
			}
			return null;
		});
	}

	public bool isEmpty() {
		lock (givers) {
			return givers.isEmpty() && takers.isEmpty();
		}
	}
}
